// 0.50.0 — a post-create.local.sh still holding a pre-0.39 seed (0.48.0 knew only the 0.39–0.47 one) is refreshed.
const RUNG = '0.50.0/refresh-pre-0.39-local-stub';
const LOCAL = '.devcontainer/post-create.local.sh';
const stub = (command) => `#!/usr/bin/env bash
# Project-specific devcontainer setup. THIS FILE IS YOURS.
#
# .devcontainer/post-create.sh is generated by @bespunky/nx-tools and is overwritten on every
# \`${command}\`. This file is created once and never regenerated, so anything you put here
# survives. It runs LAST, after workspace deps, Claude plugins and every house prerequisite — so you can
# assume a working environment.
#
# Runs in a subshell; a non-zero exit warns rather than failing the container build.
set -euo pipefail

# Example — install a project-specific tool:
# sudo apt-get update -qq && sudo apt-get install -y --no-install-recommends postgresql-client
`;
const OURS = `${stub('scaffold.sh --sync')}\nnpm i -g some-cli\n`;

export default {
  name: '0.50.0 · refresh-pre-0.39-local-stub',
  ladder: [RUNG],
  cases: [
    {
      name: 'the 0.16–0.38 seed (2c58e20): refreshed to the current stub',
      setup: (tree) => tree.write(LOCAL, stub('scaffold.sh --sync')),
      expect: (tree, t) => {
        t.hasNot(LOCAL, 'apt-get install');
        t.hasNot(LOCAL, 'scaffold.sh');
        t.has(LOCAL, 'os-packages.txt');
      },
      // Every stub the devcontainer generator ever seeded (its LOCAL_STUB at each commit on origin/development):
      //   git show 2ace14b:plugins/project-starter/skills/new-project/assets/nx-tools/src/generators/devcontainer/generator.ts
      //     — `scaffold.sh --repair` (0.15.0; 5812cb1 identical)
      //   git show 2c58e20:<same path> — `scaffold.sh --sync` (0.16.0–0.38.x, unchanged through 8ec2259) — the canonical setup
      //   git show 6a23e4e:plugins/house/engine/nx-tools/src/generators/devcontainer/generator.ts — `house.sh upgrade` (0.39.0–0.47.x)
      //   git show f0d6905:<same path> — the current stub (0.48.0; 0484236's draft never shipped alone)
      historicalShapes: [
        { name: 'the 0.15.0 seed (2ace14b)', setup: (tree) => tree.write(LOCAL, stub('scaffold.sh --repair')) },
        {
          name: 'the 0.39–0.47 seed (6a23e4e)',
          diverges: "it is 0.48.0's input (build-from-house-dockerfile refreshes it, and runs first on every ladder that meets it) — this rung alone leaves it",
          setup: (tree) => tree.write(LOCAL, stub('house.sh upgrade')),
          expect: (tree, t) => t.equal(t.read(LOCAL), stub('house.sh upgrade'), 'post-create.local.sh'),
        },
      ],
    },
    {
      name: 'a seed the project added to: theirs, untouched',
      setup: (tree) => tree.write(LOCAL, OURS),
      expect: (tree, t) => t.equal(t.read(LOCAL), OURS, 'post-create.local.sh'),
    },
    {
      name: 'no post-create.local.sh: nothing written',
      setup: () => {},
      expect: (tree, t) => t.missing(LOCAL),
    },
  ],
};
